(() => {
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return localStorage.getItem('atlas-v4-'+key)||fallback;}catch{return fallback;}};
const save=(key,value)=>{try{localStorage.setItem('atlas-v4-'+key,value);}catch{}};
let lang=read('language','zh');if(!['zh','en'].includes(lang))lang='zh';
let domain=read('domain','all');if(!['all','driving','robotics'].includes(domain))domain='all';
let font=read('font','normal');if(!['normal','large','xlarge'].includes(font))font='normal';
let open=new Set();try{open=new Set(JSON.parse(read('branches','[]')));}catch{}
let treeView=read('tree-view',window.matchMedia?.('(max-width: 780px)').matches?'list':'map');if(!['map','list'].includes(treeView))treeView='map';
let D,refs,nodes,cats,canonicalRefs;
let motion=read('motion','system');if(!['system','paused','active'].includes(motion))motion='system';
const reducedMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)');
let mediaObserver=null;
let userPausedMedia=new Set();try{userPausedMedia=new Set(JSON.parse(read('paused-media','[]')));}catch{}
const rememberMediaPause=(id,paused)=>{paused?userPausedMedia.add(id):userPausedMedia.delete(id);save('paused-media',JSON.stringify([...userPausedMedia]));};
const motionPaused=()=>motion==='paused'||(motion==='system'&&!!reducedMotion?.matches);
const t=(zh,en)=>lang==='zh'?zh:en;
const labels=()=>({all:t('全景','All fields'),common:t('共同基础','Shared foundations'),driving:t('自动驾驶','Driving'),robotics:t('机器人','Robotics')});
const uniq=a=>[...new Set(a)];
const plain=s=>String(s).replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/\*\*/g,'').replace(/^[-#]+ /gm,'');
const short=(s,n=180)=>{const p=plain(s);return p.length>n?p.slice(0,n)+'…':p;};
const visible=n=>domain==='all'||n.domains.includes('common')||n.domains.includes(domain);
const md=s=>{let value=esc(s).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');return /^- /.test(value)?`<ul>${value.split('\n').filter(Boolean).map(l=>`<li>${l.replace(/^- /,'')}</li>`).join('')}</ul>`:`<p>${value.replace(/\n/g,'<br>')}</p>`;};
const tag=d=>`<span class="chip ${esc(d)}">${esc(labels()[d]||d)}</span>`;
const activeHash=()=>location.hash.slice(1)||'home';
const countText=(n,zh,en)=>`${n} ${t(zh,en)}`;
function prepare(){
 D=window.ATLAS_I18N[lang];
 const raw=new Map(D.references.map(r=>[r.id,r]));
 const canonicalId=id=>{const seen=new Set();while(raw.has(id)&&!seen.has(id)){seen.add(id);const next=raw.get(id).canonicalId||D.aliases?.[id];if(!next||next===id||!raw.has(next))break;id=next;}return id;};
 const groups=new Map();for(const r of D.references){const id=canonicalId(r.id);if(!groups.has(id))groups.set(id,[]);groups.get(id).push(r);}
 refs=new Map();canonicalRefs=[];
 for(const [id,records] of groups){
  const primary=raw.get(id),ordered=[primary,...records.filter(r=>r.id!==id)],merged={...primary};
  for(const r of ordered)for(const [key,value] of Object.entries(r))if(merged[key]===undefined||merged[key]===null||merged[key]==='')merged[key]=value;
  merged.id=id;merged.sourceRecords=ordered;merged.nodes=uniq(ordered.flatMap(r=>r.nodes||[]));merged.domains=uniq(ordered.flatMap(r=>r.domains||[]));
  for(const field of ['boundary','repoNote','evidence'])merged[field]=uniq(ordered.map(r=>r[field]).filter(Boolean)).join(' ');
  merged.searchText=ordered.map(r=>[r.name,r.year||'',r.summary||'',r.date||'',r.boundary||'',r.revision||''].join(' ')).join(' ').toLowerCase();
  canonicalRefs.push(merged);for(const r of records)refs.set(r.id,merged);
 }
 nodes=new Map();cats=new Map();D.stages.forEach(s=>s.categories.forEach(c=>{cats.set(c.id,{...c,stage:s});c.leaves.forEach(n=>nodes.set(n.id,{...n,category:c,stage:s}));}));
}
function referenceList(ids,excluded=[]){const exclude=new Set(excluded.map(id=>refs.get(id)?.id)),seen=new Set();return ids.map(id=>refs.get(id)).filter(r=>r&&visible(r)&&!exclude.has(r.id)&&!seen.has(r.id)&&seen.add(r.id));}
function sourceVersions(r){if((r.sourceRecords?.length||0)<2)return '';return `<details class="source-versions"><summary>${t('同一作品的原始来源与版本','Original sources & versions of this work')} (${r.sourceRecords.length})</summary>${r.sourceRecords.map(v=>`<div class="source-version"><a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${esc(v.name)} ↗</a><p>${[v.dateDisplay||v.date||v.year||v.dateLabel,v.kind,v.revision?t('修订：','Revised: ')+v.revision:'',v.venue_date?t('会议：','Venue: ')+v.venue_date:''].filter(Boolean).map(esc).join(' · ')}</p>${v.dateLabel&&v.dateLabel!==v.dateDisplay?`<p>${esc(v.dateLabel)}</p>`:''}${v.repoUrl?`<a href="${esc(v.repoUrl)}" target="_blank" rel="noopener noreferrer">GitHub${v.repoLabel?' · '+esc(v.repoLabel):''} ↗</a>`:''}${v.repoNote?`<p>${esc(v.repoNote)}</p>`:''}</div>`).join('')}</details>`;}

function shell(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.documentElement.dataset.font=font;document.documentElement.dataset.motion=motionPaused()?'paused':'active';$('#motionToggle').textContent=motionPaused()?t('动态已暂停','Motion paused'):t('减少动态','Reduce motion');$('#motionToggle').setAttribute('aria-pressed',String(motionPaused()));$('#skip').textContent=t('跳到主要内容','Skip to main content');$('#menuToggle').setAttribute('aria-label',t('展开导航','Toggle navigation'));$('#openSearch').setAttribute('aria-label',t('搜索知识树','Search the atlas'));$('#searchLabel').textContent=t('搜索','Search');$('#languageGroup').setAttribute('aria-label',t('页面语言','Page language'));$$('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});$('#fontSize').innerHTML=[['normal',t('标准','Standard')],['large',t('大字','Large')],['xlarge',t('特大','Extra large')]].map(([v,label])=>`<option value="${v}" ${font===v?'selected':''}>${label}</option>`).join('');$('#fontSize').setAttribute('aria-label',t('文字大小','Text size'));$('#domainGroup').setAttribute('aria-label',t('领域视图','Field view'));$('#domainGroup').innerHTML=['all','driving','robotics'].map(d=>`<button data-domain="${d}" class="${d===domain?'active':''}" aria-pressed="${d===domain}">${labels()[d]}</button>`).join('');$('#breadcrumbs').setAttribute('aria-label',t('路径导航','Breadcrumbs'));$('#footer').innerHTML=`<span>${t('非营利研究整理','Non-profit research collection')} · ${D.updated}</span><span><a href="https://github.com/Weizhi-T/roadmap-for-autonomous-driving-and-robotics/issues" target="_blank" rel="noopener noreferrer">${t('如有侵权，请联系删除','Rights concerns? Contact us for removal')}</a> · <a href="#guide">${t('来源与许可','Sources & licenses')}</a> · <a href="guides/">${t('专题导读','Reading guides')}</a></span>`;$('#searchTitle').textContent=t('探索整个知识树','Explore the whole atlas');$('#closeSearch').setAttribute('aria-label',t('关闭搜索','Close search'));$('#searchInput').placeholder=t('试试 JEPA、模仿学习、闭环评测…','Try JEPA, imitation learning, closed-loop evaluation…');$('#searchInput').setAttribute('aria-label',t('搜索方法、模型和论文','Search methods, models and papers'));$('#searchFoot').textContent=t('Enter 打开首项 · Esc 关闭 · 支持中英文关键词','Enter opens the first result · Esc closes · Chinese and English search');}
function primaryEntries(){return [['01','atlas',t('交互全景图','Interactive atlas')],['02','news',t('研究导读','Field notes')],['03','topics',t('深度思考课题','Research questions')],['04','arxiv',t('arXiv 文章周更新','Weekly arXiv papers')],['05','principles',t('算法原理','Algorithm principles')],['06','reproductions',t('项目复现','Project reproductions')]];}
function nav(){const fullHash=activeHash(),h=fullHash.startsWith('news/')?'news':fullHash,atlasActive=['home','atlas'].includes(h)||/^(stage|category|node)\//.test(h),st=h.startsWith('stage/')?h.split('/')[1]:h.startsWith('category/')?cats.get(h.split('/')[1])?.stage.id:h.startsWith('node/')?nodes.get(h.split('/')[1])?.stage.id:null;$('#sidebar').innerHTML=`<a href="#home" class="brand"><span class="brand-icon" aria-hidden="true">⌘</span><span>${t('具身智能','Embodied intelligence')}<small>RESEARCH ATLAS</small></span></a><div class="nav-label">${t('目录','DIRECTORY')}</div><nav aria-label="${t('主导航','Main navigation')}">${primaryEntries().map(([num,route,label],index)=>`<div class="nav-parent"><a class="nav-item ${h===route||(index===0&&atlasActive)?'active':''}" href="#${route}" ${(h===route||(index===0&&atlasActive))?'aria-current="page"':''}><span class="nav-num">${num}</span><span>${label}</span></a>${index===0?`<div class="stage-shortcuts" aria-label="${t('全景图研发环节','Atlas research stages')}">${D.stages.map(s=>`<a class="nav-item loop-link ${st===s.id?'active':''}" href="#stage/${s.id}"><span class="nav-num">${s.number}</span>${esc(s.title)}</a>`).join('')}</div>`:''}</div>`).join('')}<div class="nav-gap"></div><a class="nav-item nav-secondary ${h==='references'||h.startsWith('references/')?'active':''}" href="#references" ${h==='references'||h.startsWith('references/')?'aria-current="page"':''}>${t('参考文献库','Reference library')}</a><a class="nav-item nav-secondary ${h==='guide'?'active':''}" href="#guide">${t('来源、许可与说明','Sources, licenses & notes')}</a></nav><div class="sidebar-bottom"><div class="side-status">${t('中英双语 · 离线阅读','Bilingual · Offline reading')}</div></div>`;}

function crumb(parts=[],section='atlas'){const prefix=[[t('首页','Home'),'home']];if(section==='atlas'&&activeHash()!=='home')prefix.push([t('交互全景图','Interactive atlas'),'atlas']);$('#breadcrumbs').innerHTML=[...prefix,...parts].map(([text,h],i,a)=>i<a.length-1?`<a href="#${h}">${esc(text)}</a><span aria-hidden="true">/</span>`:`<span class="current" aria-current="page">${esc(text)}</span>`).join('');}

function header(eye,title,desc){return `<div class="page-header"><div class="eyebrow">${esc(eye)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;}
function informationNote(title,body,cls=''){return `<details class="information-note ${cls}"><summary>${title}</summary><div>${body}</div></details>`;}
function domainNote(){return domain==='all'?'':informationNote(t('领域视图：','Field view: ')+labels()[domain],t('保留共同基础与本领域节点；同一方法可以跨领域使用。','Shared foundations and matching field nodes are included. Methods can cross fields.'));}
function directoryCards(){return `<nav class="directory-cards" aria-label="${t('研究栏目','Research sections')}">${primaryEntries().map(([num,route,label],i)=>`<a href="#${route}" class="directory-card"><span>${num}</span><strong>${label}</strong><small>${i===0?t('4 个环节 · 62 个方法','4 stages · 62 methods'):route==='news'?t('博客、项目与图谱','Blogs, projects & atlases'):t('待建设','Coming soon')}</small><b aria-hidden="true">↗</b></a>`).join('')}</nav>`;}
function reservedPage(route){const entry=primaryEntries().find(x=>x[1]===route);crumb([[entry[2],route]],'root');const description=route==='news'?t('面向具身智能与自动驾驶的前沿进展。','Frontier developments in embodied intelligence and autonomous driving.'):route==='topics'?t('从已有证据出发，形成可检验的问题。','From existing evidence to testable questions.'):route==='principles'?t('从假设、目标与推导理解算法。','Understand algorithms through assumptions, objectives and derivations.'):route==='reproductions'?t('从环境、数据与评测流程走向可复现实现。','From environments, data and evaluation protocols to reproducible implementations.'):t('按周整理相关论文的入口。','A place for weekly collections of relevant papers.');return header(entry[0],entry[2],description)+`<section class="reserved-section"><span class="reserved-status">${t('待建设','Coming soon')}</span><h2>${t('独立栏目，内容待补充。','Dedicated section, content pending.')}</h2><p>${route==='arxiv'?t('尚未配置自动更新，也暂无周刊内容。','Automatic updates are not configured, and no weekly editions are available yet.'):t('尚未发布内容。','No content has been published yet.')}</p><a class="text-link" href="#atlas">${t('先探索交互全景图','Explore the atlas')} ↗</a></section>`;}

const visibleBranch=b=>(!b.domains||domain==='all'||b.domains.includes('common')||b.domains.includes(domain))&&((b.references||[]).some(id=>refs.has(id)&&visible(refs.get(id)))||(b.children||[]).some(visibleBranch));
function branchList(n){return (n.branches?.length?n.branches:[...(n.references.length?[{id:n.id+'-foundations',title:t('基础机制与代表作','Foundations & mechanisms'),idea:t('从代表性工作理解这条路线的技术机制。','Understand this route through representative works.'),references:n.references}]:[]),...(n.latest.length?[{id:n.id+'-recent',title:t('近期进展与变体','Recent advances & variants'),idea:t('沿已核验的原始来源查看近期变化。','Follow recent developments through checked original sources.'),references:n.latest}]:[])]).filter(visibleBranch);}
function allBranches(){const out=[];function add(id,depth,parent){out.push({id,depth,parent});}function walk(b,depth,parent){add(b.id,depth,parent);(b.children||[]).filter(visibleBranch).forEach(c=>walk(c,depth+1,b.id));}D.stages.forEach(s=>{add(s.id,0,null);s.categories.filter(c=>c.leaves.some(visible)).forEach(c=>{add(c.id,1,s.id);c.leaves.filter(visible).forEach(n=>{add(n.id,2,c.id);branchList(n).forEach(b=>walk(b,3,n.id));});});});return out;}
function tinyPaper(r){if(!r)return '';return `<article class="evidence-leaf" data-reference-id="${esc(r.id)}"><div class="evidence-date"><time>${esc(r.dateDisplay||r.date||r.year||r.dateLabel||t('日期未标注','Date not recorded'))}</time></div><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.name)} <span aria-hidden="true">↗</span></a><p>${esc(short(r.summary||t('旧版保留来源。请从原文核对具体贡献与适用条件。','Retained source. Consult the original for its specific contribution and conditions.'),lang==='zh'?110:240))}</p>${r.projectUrl&&r.projectUrl!==r.url&&r.projectUrl!==r.repoUrl?`<a class="repository-link" href="${esc(r.projectUrl)}" target="_blank" rel="noopener noreferrer">${t('项目页面','Project page')} ↗</a>`:''}${r.repoUrl?`<a class="repository-link" href="${esc(r.repoUrl)}" target="_blank" rel="noopener noreferrer">GitHub${r.repoLabel?` · ${esc(r.repoLabel)}`:''} ↗</a>`:''}${sourceVersions(r)}</article>`;}
function subBranch(b,level=4){const expanded=open.has(b.id);const children=(b.children||[]).filter(visibleBranch);const list=referenceList(b.references||[]);return `<div class="sub-branch" data-level="${level}"><button class="sub-toggle" data-expand="${esc(b.id)}" aria-expanded="${expanded}" aria-controls="branch-${esc(b.id)}"><span class="tree-chevron" aria-hidden="true">${expanded?'−':'+'}</span><span>${esc(b.title)}</span><small>${children.length||list.length}</small></button><div class="sub-content" id="branch-${esc(b.id)}" ${expanded?'':'hidden'}>${b.idea?`<p class="branch-idea">${esc(b.idea)}</p>`:''}${children.map(c=>subBranch(c,level+1)).join('')}${list.length?`<div class="evidence-list">${list.map(tinyPaper).join('')}</div>`:''}</div></div>`;}
function methodBranch(n){const expanded=open.has(n.id),branches=branchList(n);return `<div class="method-branch" data-level="3"><button class="method-toggle" data-expand="${n.id}" aria-expanded="${expanded}" aria-controls="branch-${n.id}"><span class="tree-chevron" aria-hidden="true">${expanded?'−':'+'}</span><span>${esc(n.title)}</span><small>${referenceList([...n.references,...n.latest]).length}</small></button><div class="method-content" id="branch-${n.id}" ${expanded?'':'hidden'}>${methodVisual(n,'tree')}<p class="method-idea">${esc(n.idea||short(n.body[0],lang==='zh'?90:200))}</p><a class="detail-link method-detail" href="#node/${n.id}">${t('完整机制与边界','Full mechanism & boundaries')} ↗</a>${branches.length?branches.map(b=>subBranch(b)).join(''):`<p class="branch-idea">${t('本节点保留方法说明，尚无独立文献条目。','Method explanation retained; no dedicated evidence entry yet.')}</p>`}</div></div>`;}
function tree(){return `<section class="tree-shell" data-view="${treeView}" id="panorama" aria-label="${t('可展开技术全景树','Expandable research tree')}"><div class="tree-controls"><span class="tree-hint">${t('从环节到机制，再到原始证据','FROM STAGES TO MECHANISMS TO EVIDENCE')}</span><div class="tree-view" role="group" aria-label="${t('树形视图','Tree view')}">${[['map',t('图谱','Map')],['list',t('列表','Outline')]].map(([v,l])=>`<button data-view="${v}" class="${treeView===v?'active':''}" aria-pressed="${treeView===v}">${l}</button>`).join('')}</div><button class="outline-button" data-action="expand-level">${t('展开一层','Expand one level')}</button><button class="outline-button" data-action="expand-all">${t('展开全部','Expand all')}</button><button class="outline-button" data-action="collapse-all">${t('收起全部','Collapse all')}</button><button class="outline-button" data-action="fullscreen" ${!document.fullscreenEnabled?'hidden':''}>${document.fullscreenElement?t('退出全屏','Exit full screen'):t('全屏','Full screen')}</button></div><div class="tree-root"><span class="root-kicker">EMBODIED INTELLIGENCE</span><strong>${t('自动驾驶 × 机器人','Autonomous driving × Robotics')}</strong><small>${t('共同基础 · 不同机体 · 一个研发闭环','Shared foundations · Different bodies · One research loop')}</small></div><div class="tree-grid">${D.stages.map(s=>{const active=open.has(s.id);const categories=s.categories.filter(c=>c.leaves.some(visible));return `<section class="stage-branch ${s.color} ${active?'expanded':''}" data-level="1"><button class="stage-toggle" data-expand="${s.id}" aria-expanded="${active}" aria-controls="branch-${s.id}"><span class="stage-number">${s.number} / ${t('研发环节','RESEARCH STAGE')}</span><strong>${esc(s.title)}</strong><span class="subtitle">${esc(s.subtitle)}</span><span class="branch-foot"><span>${countText(categories.length,'类方法','families')} · ${countText(categories.flatMap(c=>c.leaves.filter(visible)).length,'方法','methods')}</span><span class="toggle-indicator" aria-hidden="true">${active?'−':'+'}</span></span></button><div class="tree-children" id="branch-${s.id}" ${active?'':'hidden'}>${categories.map(c=>{const leaves=c.leaves.filter(visible),expanded=open.has(c.id);return `<div class="category-branch ${expanded?'expanded':''}" data-level="2"><button class="category-toggle" data-expand="${c.id}" aria-expanded="${expanded}" aria-controls="branch-${c.id}"><span class="category-index">${c.id.toUpperCase()}</span><span>${esc(c.title)}</span><span class="cat-count">${leaves.length}</span><span aria-hidden="true">${expanded?'−':'+'}</span></button><div class="tree-leaves" id="branch-${c.id}" ${expanded?'':'hidden'}>${categoryVisual(c,true)}${leaves.map(methodBranch).join('')}<a class="branch-overview" href="#category/${c.id}">${t('阅读方法族概览','Read family overview')} ↗</a></div></div>`;}).join('')}<a class="branch-overview stage-overview" href="#stage/${s.id}">${t('阅读本环节概览','Read stage overview')} ↗</a></div></section>`;}).join('')}</div><details class="tree-legend"><summary>${t('层级说明','Hierarchy')}</summary><p>${t('环节 → 方法族 → 细分方法 → 技术分支 → 论文与资源。分支可继续延伸；同一文献可连接多条路线。','Stage → family → method → technical branch → papers & resources. Branches can extend further; one source may connect several routes.')}</p></details></section>`;}
function researchLoop(){
 const paused=motionPaused(),cards=[
  {id:'data',color:'mint',number:'01',title:t('数据','Data'),subtitle:t('采集 · 仿真 · 世界建模','Collect · Simulate · Model')},
  {id:'training',color:'violet',number:'02',title:t('训练','Training'),subtitle:t('学习目标 · 优化 · 适配','Objectives · Optimize · Adapt')},
  {id:'execution',color:'peach',number:'03',title:t('执行','Execution'),subtitle:t('感知 · 规划 · 行动','Perceive · Plan · Act')},
  {id:'feedback',color:'blue',number:'04',title:t('评测与反馈','Evaluate & refine'),subtitle:t('测试 · 诊断 · 更新','Test · Diagnose · Update')}
 ];
 return `<section class="research-loop" aria-labelledby="researchLoopTitle" data-research-loop><div class="loop-topline"><h3 id="researchLoopTitle">THE RESEARCH LOOP</h3><button class="loop-motion" data-action="toggle-motion" data-paused="${paused}" aria-describedby="loopMotionHelp">${paused?t('播放动态','Play motion'):t('暂停动态','Pause motion')}</button></div><div class="loop-surface"><svg class="loop-traces" viewBox="0 0 1000 520" preserveAspectRatio="none" aria-hidden="true" focusable="false"><defs><pattern id="loop-grid" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b9cbbb" opacity=".5"/></pattern><marker id="loop-arrow" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M1 1L7 5L1 9" fill="none" stroke="#81998d" stroke-width="1.6"/></marker></defs><rect x="0" y="0" width="1000" height="520" fill="url(#loop-grid)"/><path class="loop-rail" d="M185 110H815Q850 110 850 145V375Q850 410 815 410H185Q150 410 150 375V145Q150 110 185 110Z" pathLength="100"/><path class="loop-trail" d="M185 110H815Q850 110 850 145V375Q850 410 815 410H185Q150 410 150 375V145Q150 110 185 110Z" pathLength="100"/><path class="loop-signal" d="M185 110H815Q850 110 850 145V375Q850 410 815 410H185Q150 410 150 375V145Q150 110 185 110Z" pathLength="100"/><path class="loop-direction" d="M460 110H540 M850 235V285 M540 410H460 M150 285V235" marker-end="url(#loop-arrow)"/><path class="loop-return" d="M270 370Q395 278 470 260 M530 260Q610 197 730 150"/><circle cx="500" cy="260" r="105" class="loop-orbit"/></svg><div class="loop-center"><svg class="loop-center-spin" viewBox="0 0 160 160" aria-hidden="true" focusable="false"><circle cx="80" cy="80" r="69" fill="none" stroke="#b5cabe" stroke-width="1"/><path d="M80 11 A69 69 0 0 1 148 69 M80 149 A69 69 0 0 1 12 91" fill="none" stroke="#5e8f77" stroke-width="3" stroke-linecap="round"/><path d="M141 66L148 73L153 64 M19 94L12 87L7 96" fill="none" stroke="#5e8f77" stroke-width="2" stroke-linecap="round"/></svg><strong>${t('持续改进','Continuous refinement')}</strong><small>ITERATE</small></div>${cards.map(c=>`<a class="loop-node loop-${c.id} ${c.color}" href="#stage/${c.id}" aria-label="${esc(t('进入','Explore ')+c.title)}"><span class="loop-node-top"><b>${c.number}</b><span aria-hidden="true">↗</span></span><strong>${esc(c.title)}</strong><small>${esc(c.subtitle)}</small></a>`).join('')}</div><p class="loop-caption">${t('反馈可回到数据、训练或执行。','Feedback can return to data, training or execution.')} <span>${t('点击节点探索','Select a node to explore')}</span></p><span id="loopMotionHelp" class="sr-only">${t('此按钮控制页面动画与自动视频播放。','This button controls page animation and automatic video playback.')}</span><span class="sr-only">${t('这是研发闭环，不表示运行时每一步都会训练模型；部署模型可以冻结。','This is a research and development loop, not a claim that deployed models learn at every runtime step; model parameters may be frozen.')}</span></section>`;
}

function overviewPanels(){
 const shown=canonicalRefs.filter(visible),recent=shown.filter(r=>r.section==='latest').length,methodCount=[...nodes.values()].filter(visible).length;
 return `<section class="overview-lower" aria-label="${t('功能索引与证据库','Function index and evidence library')}"><article class="panel function-panel" aria-labelledby="functionIndexTitle"><div class="panel-kicker">ANOTHER WAY IN</div><h2 id="functionIndexTitle">${t('也可以从系统功能开始','Another way in: system functions')}</h2><p>${t('共享方法与领域实现相互连接。功能索引不要求系统按固定顺序串行，联合架构也可以保留显式中间表示。','Shared methods connect to domain implementations. These functions need not run in a fixed serial order; joint architectures can retain explicit intermediate representations.')}</p><nav class="path-row" aria-label="${t('系统功能入口','System function shortcuts')}"><a href="#node/3a-1">${t('感知与状态估计','Perception & state estimation')}</a><span aria-hidden="true">→</span><a href="#category/2b">${t('表示与预测','Representation & prediction')}</a><span aria-hidden="true">→</span><a href="#node/3a-3">${t('决策、规划与控制','Decision, planning & control')}</a></nav><div class="function-related"><span>${t('继续探索','Explore further')}</span><a href="#category/1e">${t('生成与世界模型','Generative & world models')}</a>${domain!=='robotics'?`<a href="#node/3a-2">${t('参与者预测与交互','Agent prediction & interaction')}</a>`:''}</div></article><article class="panel evidence-panel" aria-labelledby="evidenceLibraryTitle"><div class="panel-kicker">A TRACEABLE KNOWLEDGE BASE</div><h2 id="evidenceLibraryTitle">${t('每条路线，都能回到原始证据','Every route leads back to original evidence')}</h2><p>${t('代表作建立坐标，近期收录跟踪变化。保留来源、核查状态与边界，不把榜单当作能力证明。','Representative works establish context; recent additions track change. Sources, checks and scope remain traceable. Leaderboards alone do not prove capability.')}</p><div class="overview-stats"><a href="#references" class="overview-stat" data-stat="sources"><strong>${shown.length}</strong><span>${t('论文与官方资料','Papers & official sources')}</span></a><a href="#references/recent" class="overview-stat" data-stat="recent"><strong>${recent}</strong><span>${t('近期收录','Recent additions')}</span></a><button class="overview-stat" data-action="explore" data-stat="methods"><strong>${methodCount}</strong><span>${t('方法节点','Method nodes')}</span></button></div><p class="overview-stat-note">${t('按当前领域视图计数；同一作品合并统计。“近期收录”沿用文献库分组，不等同于近期发表。','Counts follow the current field, with duplicate works merged. “Recent additions” follows the library grouping, not a publication-date window.')}</p></article></section>`;
}
function homeHero(){
 if(domain==='all')return `<section class="hero-world"><img class="hero-image" src="assets/embodied-world.png" width="1752" height="897" alt="${t('原创概念图：城市自动驾驶汽车、工业机械臂与人形机器人、仓储移动机器人、山地四足机器人与空中无人机。','Original conceptual artwork: autonomous city vehicles, industrial manipulators and humanoids, warehouse robots, a legged robot and a drone.')}" fetchpriority="high"><div class="hero-copy"><div class="eyebrow">THE EMBODIED INTELLIGENCE ATLAS</div><h1>${t('从观察世界，<br>到<em>可靠行动。</em>','From seeing the world<br>to <em>acting in it.</em>')}</h1><p>${t('自动驾驶与机器人的研究知识树。<br>逐层展开方法，让每一条路线回到证据。','A research tree for autonomous driving and robotics.<br>Unfold the methods. Follow every route to its evidence.')}</p><button class="hero-cta" data-action="explore">${t('开始探索知识树','Explore the knowledge tree')} <span aria-hidden="true">↓</span></button><div class="hero-facts"><span><b>${nodes.size}</b>${t('方法节点','method nodes')}</span><span><b>${canonicalRefs.length}</b>${t('独立来源','distinct sources')}</span><span><b>5+</b>${t('探索层级','exploration levels')}</span></div></div><div class="hero-caption">${t('原创概念图','Original conceptual artwork')}</div></section>`;
 const driving=domain==='driving',m=mediaCatalog().find(m=>m.id===(driving?'nuscenes-camera-annotations':'aloha-teleoperation-excerpt'));
 const title=driving?t('从辅助驾驶，<br>走向有边界的自动驾驶。','From driver assistance<br>to automated driving.'):t('从操作物体，<br>到协作完成任务。','From manipulating objects<br>to completing useful tasks.');
 const intro=driving?t('关键不在功能数量，而在谁完成驾驶任务、监测环境，以及边界到来时如何响应。','The distinction is who performs the driving task, monitors the environment and responds when limits are reached.'):t('围绕工业操作、家庭服务、移动物流与户外作业，连接感知、动作和长程任务。','Connect perception, action and long-horizon tasks across industrial work, home services, mobile logistics and field operations.');
 const credit=m?`<figcaption><span>${driving?t('nuScenes · 实际道路数据与目标标注','nuScenes · Recorded road data and object annotations'):t('ALOHA · 双臂遥操作演示帧','ALOHA · Frame from bimanual teleoperation demo')}</span>${informationNote(t('来源','Source'),`<p>${esc(m.attribution)}</p><p>${esc(driving?m.caption:t('原演示视频封面帧，保留完整画面、原水印与速度标识。','Poster frame from the source demo, retaining the full frame, watermark and speed label.'))}</p><a href="${esc(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('原始来源','Original source')} ↗</a>${m.licenseUrl?` · <a href="${esc(m.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(mediaLicense(m))}</a>`:`<p>${esc(mediaLicense(m))}</p>`}`,'hero-source-details')}</figcaption>`:'';
 return `<section class="domain-hero ${domain}" data-home-theme="${domain}" aria-labelledby="domainHeroTitle"><div class="domain-hero-copy"><div class="eyebrow">${driving?'AUTONOMOUS DRIVING':'ROBOTICS IN PRACTICE'}</div><h1 id="domainHeroTitle">${title}</h1><p>${intro}</p><button class="hero-cta" data-action="explore">${driving?t('探索驾驶方法','Explore driving methods'):t('探索机器人方法','Explore robotics methods')} <span aria-hidden="true">↓</span></button><div class="hero-facts"><span><b>${[...nodes.values()].filter(visible).length}</b>${t('方法节点','method nodes')}</span><span><b>${canonicalRefs.filter(visible).length}</b>${t('独立来源','distinct sources')}</span><span><b>${D.stages.length}</b>${t('研发环节','research stages')}</span></div></div>${m?`<figure class="domain-hero-figure"><img src="${esc(m.poster||m.src)}" alt="${esc(driving?m.alt:t('ALOHA 原演示画面：双臂机器人在桌面操作金属部件，保留原视频十倍速度和实验室水印标识。','Original ALOHA demo frame: two robot arms manipulating metal parts on a tabletop, with the original 10x speed label and lab watermark.'))}" decoding="async" fetchpriority="high">${credit}</figure>`:''}</section>`;
}
function homeContextStrip(){
 if(domain==='driving')return `<section class="domain-topic driving-levels" aria-labelledby="drivingLevelsTitle"><div class="topic-heading"><div><div class="eyebrow">WHO DOES WHAT?</div><h2 id="drivingLevelsTitle">${t('L1–L4：驾驶任务与接管责任','L1–L4: driving roles and fallback')}</h2></div><span>${t('按 SAE 自动化分级理解','Understanding the SAE levels')}</span></div><div class="topic-grid">${[
 ['L1',t('驾驶辅助','Driver assistance'),t('系统持续控制转向或加减速其中一项；驾驶员完成其余驾驶任务，并持续监测环境。','The system provides sustained steering OR acceleration/braking support. The driver performs the rest of the driving task and monitors the environment.')],
 ['L2',t('部分驾驶自动化','Partial driving automation'),t('系统同时控制转向和加减速；驾驶员仍持续监督、监测环境，并负责必要的响应。','The system supports steering AND acceleration/braking. The driver still continuously supervises, monitors the environment and responds as needed.')],
 ['L3',t('有条件驾驶自动化','Conditional driving automation'),t('在设计运行域内，系统完成驾驶任务并监测环境；用户须准备响应接管请求或明显的驾驶相关故障。','Within its operational design domain, the system performs the dynamic driving task and monitors the environment. A fallback-ready user must respond to a takeover request or an evident driving-relevant failure.')],
 ['L4',t('高度驾驶自动化','High driving automation'),t('系统在设计运行域内驾驶，并承担必要回退，不依赖人类接管；不承诺域外继续驾驶。','The system drives within its operational design domain and manages fallback without human takeover. Continued driving beyond that domain is not promised.')]
 ].map(([level,title,body])=>`<article class="topic-card"><span class="topic-index">${level}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><p class="topic-note">${t('设计运行域（ODD）限定道路、速度、天气等适用条件。等级描述当时启用功能的人机分工，不是安全评分，也不能由商品名、功能名称或演示片段直接判定。','An operational design domain (ODD) sets conditions such as roads, speeds and weather. Levels describe the roles of the active feature, not a safety rating. A product name, feature name or demo alone does not establish the level.')}</p><details class="topic-sources"><summary>${t('分级依据','Level definitions')}</summary><a href="https://saemobilus.sae.org/standards/j3016_202609-taxonomy-definitions-terms-related-driving-automation-systems-road-motor-vehicles" target="_blank" rel="noopener noreferrer">SAE J3016_202609 ↗</a> · <a href="https://www.nhtsa.gov/vehicle-safety/automated-vehicle-safety" target="_blank" rel="noopener noreferrer">NHTSA ↗</a></details></section>`;
 if(domain==='robotics')return `<section class="domain-topic robotics-applications" aria-labelledby="roboticsApplicationsTitle"><div class="topic-heading"><div><div class="eyebrow">TASKS IN THE PHYSICAL WORLD</div><h2 id="roboticsApplicationsTitle">${t('机器人可以走进哪些任务？','Where can robots be useful?')}</h2></div><span>${t('从应用需求进入方法','Start with an application')}</span></div><div class="topic-grid">${[
 ['01',t('工业与制造','Industry & manufacturing'),t('装配、分拣、检测与精细操作，关注精度、节拍和接触控制。','Assembly, sorting, inspection and precision manipulation, with accuracy, cycle time and contact control.'),'#node/3a-3'],
 ['02',t('家庭与服务','Home & service'),t('取放、整理与协作，关注开放环境中的理解、泛化与安全求助。','Picking, tidying and collaboration in open-ended environments, with generalization and safe assistance.'),'#category/3e'],
 ['03',t('仓储与移动物流','Warehousing & logistics'),t('搬运、配送与自主导航，连接路径规划、避障和长期任务执行。','Transport, delivery and navigation, combining route planning, obstacle avoidance and long-horizon execution.'),'#category/3a'],
 ['04',t('户外与特种作业','Field & specialist work'),t('巡检、搜救与复杂地形通行，关注机体适应、可靠性和运行边界。','Inspection, search and rescue, and difficult terrain, with embodiment adaptation, reliability and operating limits.'),'#category/3f']
 ].map(([i,title,body,href])=>`<a class="topic-card" href="${href}"><span class="topic-index">${i}</span><h3>${title} <span aria-hidden="true">↗</span></h3><p>${body}</p><span class="topic-entry">${t('方法入口：','Method entry: ')}${esc((href.startsWith('#node/')?nodes:cats).get(href.split('/')[1])?.title||'')}</span></a>`).join('')}</div><p class="topic-note">${t('这些是应用入口，不表示同一机器人或模型已覆盖全部任务；演示与能力结论仍以各项目证据为准。','These are application entry points, not a claim that one robot or model covers every task. Capability claims remain tied to each project’s evidence.')}</p></section>`;
 return `<section class="embodiment-strip" aria-label="${t('机体与应用场景','Embodiments and scenarios')}">${[[t('道路交通','ON THE ROAD'),t('自动驾驶','Autonomous vehicles')],[t('家庭与工业','AT HOME & AT WORK'),t('机械臂与人形机器人','Manipulators & humanoids')],[t('仓储与配送','MOVING THROUGH SPACES'),t('移动与配送机器人','Mobile & delivery robots')],[t('复杂地形与空域','OVER LAND & IN THE AIR'),t('足式机器人与无人机','Legged robots & drones')]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</section>`;
}
let comparison = 'evaluation';

function comparisonTopics() {
 const feedbackNode = domain === 'robotics' ? '4b-2' : '4b-1';
 return [
  {id:'evaluation', label:t('评测协议','Evaluation'), question:t('动作改变以后，下一帧会跟着变吗？','When an action changes, does the next observation change?'), sides:[
   [t('固定记录','Fixed record'), '4a-1', t('预测轨迹与记录轨迹逐点比较。换一个预测，记录中的观测仍然相同。','Compare a prediction against a recorded trajectory. Changing the prediction leaves the logged observations fixed.')],
   [t('闭环交互','Closed-loop interaction'), feedbackNode, t('执行动作，环境推进，再根据新观测决策。比较结果时，也要看环境怎样回应动作。','An action advances the environment. The next decision uses a new observation. Read the results together with the environment’s response model.')]
  ]},
  {id:'actions',label:t('动作生成','Actions'),question:t('模型一次生成什么？机器人执行了哪一部分？','What does the model predict, and which part gets executed?'),sides:[
   [t('动作分块','Action chunks'),'2c-1',t('一次给出多步动作，关注时间跨度与实际执行步数。动作块也可以由扩散策略生成。','A policy predicts several actions together. Compare the prediction horizon with how many steps actually run. A diffusion policy can also output chunks.')],
   [t('扩散与流匹配','Diffusion & flow matching'),'2c-3',t('关注动作样本如何从噪声逐步生成。执行时还要另行决定多久重新观测、重新规划。','Follow how a sample evolves from noise into an action. How often the policy observes and replans is a separate execution choice.')]
  ]},
  {id:'worlds',label:t('世界模型','World models'),question:t('模型需要重建可见画面，还是预测有用的状态？','Does the model generate a view or predict a useful state?'),sides:[
   [t('生成可见观测','Generate observations'),'1e-1',t('查看相机或其他传感器序列是否连贯，以及条件动作是否真正改变了生成结果。','Inspect coherence across generated observations, then check whether conditioning actions change the outcome.')],
   [t('预测潜在状态','Predict latent states'),'1e-2',t('模型可以在特征空间预测未来。还需核对该表示保留了哪些会影响控制的变化。','A model can predict the future in feature space. Check which changes relevant to control survive in that representation.')]
  ]}
 ];
}
function comparisonBody(entry) {
 return `<h3>${esc(entry.question)}</h3><div class="comparison-pair">${entry.sides.map(([label,id,body])=>`<article><span class="comparison-label">${esc(label)}</span><p>${esc(body)}</p><a href="#node/${id}">${esc(nodes.get(id).title)} <span aria-hidden="true">→</span></a></article>`).join('')}</div>`;
}
function comparisonPanel() {
 const topics=comparisonTopics(), entry=topics.find(item=>item.id===comparison)||topics[0];
 return `<section class="comparison" aria-labelledby="comparisonTitle"><div class="comparison-top"><h2 id="comparisonTitle">${t('方法对照','Compare methods')}</h2><div class="comparison-choices" role="group" aria-label="${t('对照主题','Comparison topic')}">${topics.map(item=>`<button data-compare="${item.id}" aria-controls="comparisonBody" aria-pressed="${entry.id===item.id}">${esc(item.label)}</button>`).join('')}</div></div><div id="comparisonBody" aria-live="polite">${comparisonBody(entry)}</div></section>`;
}

function fieldNotes(filter) {
 const tabs=[['all',t('全部','All')],['articles',t('博客与发布','Blogs & releases')],['atlases',t('图谱与项目','Atlases & projects')]];
 const current=tabs.some(([key])=>key===filter)?filter:'all';
 const rows=D.fieldNotes.filter(visible).filter(item=>current==='all'||(current==='atlases')===(item.kind==='atlas'));
 crumb([[t('研究导读','Field notes'),'news']],'root');
 const label=kind=>kind==='atlas'?t('研究网站','Project site'):kind==='release'?t('官方发布','Release'):t('团队博客','Team blog');
 return `<section class="notes-intro"><div><h1>${t('研究导读','Field notes')}</h1><p>${t('从研究团队的文章、演示和专题图谱，回到它们解释的方法。','Follow a research team’s article, demonstration or atlas back to the method it explains.')}</p></div><a href="#references/recent">${t('近期论文','Recent papers')} →</a></section><nav class="notes-filters" aria-label="${t('资料类型','Resource type')}">${tabs.map(([key,title])=>`<a href="#news${key==='all'?'':'/'+key}" ${current===key?'aria-current="page"':''}>${title}</a>`).join('')}</nav><div class="note-grid">${rows.map(item=>`<article class="note-entry"><div class="note-dateline"><span>${esc(label(item.kind))}</span>${item.date?`<time datetime="${esc(item.date)}">${esc(item.date)}</time>`:''}</div><h2><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a></h2><p>${esc(item.body)}</p><div class="note-byline"><small>${esc(item.source)}</small><a href="#node/${esc(item.node)}">${esc(nodes.get(item.node).title)} →</a></div></article>`).join('')}</div>`;
}

function repositoryCommunity(){
 const repository='https://github.com/Weizhi-T/roadmap-for-autonomous-driving-and-robotics';
 return `<section class="repo-community" aria-labelledby="repositoryTitle"><div class="eyebrow">OPEN RESEARCH · GITHUB</div><h2 id="repositoryTitle">${t('欢迎阅读，一起讨论与完善。','Read, discuss and help improve the atlas.')}</h2><p>${t('如果这张图谱对你有帮助，欢迎到 GitHub 给仓库点一颗 Star。发现问题、希望补充方法或提出功能需求，都可以通过公开 Issues 留言。','If this atlas is useful, consider starring the repository on GitHub. Use public Issues to discuss ideas, report problems, suggest methods or request features.')}</p><p class="repo-name"><a href="${repository}" target="_blank" rel="noopener noreferrer">Weizhi-T / roadmap-for-autonomous-driving-and-robotics ↗</a></p><div class="repo-actions"><a href="${repository}" target="_blank" rel="noopener noreferrer">☆ ${t('前往 GitHub 点 Star','Star on GitHub')} ↗</a><a href="${repository}/issues" target="_blank" rel="noopener noreferrer">${t('阅读讨论 / 留言','Read discussions / Comment')} ↗</a><a href="${repository}/issues/new" target="_blank" rel="noopener noreferrer">＋ ${t('提交建议或需求','Suggest an idea / Request a feature')} ↗</a></div><div class="community-interactions"><button type="button" class="bookmark-button" data-community-bookmark>☆ ${t('收藏本网址','Bookmark this page')}</button><button type="button" class="like-button" data-community-like disabled><span aria-hidden="true" class="like-heart">♥</span> ${t('点赞本项目','Like this project')}</button><span class="like-total">${t('共享点赞','Shared likes')} <strong data-community-count>—</strong></span></div><p class="community-help" data-community-status role="status" aria-live="polite">${t('正在连接共享点赞，起始值为 200。','Connecting shared likes. Starting value: 200.')}</p><p class="community-help" data-bookmark-status role="status" aria-live="polite"></p><p class="repo-note">${t('Star 按钮会打开仓库，由你在 GitHub 上确认；留言和提交需求可能需要登录。Issues 内容公开，请勿提交个人或敏感信息。','The Star link opens the repository for you to star on GitHub. Commenting or creating an issue may require sign-in. Issues are public; do not include personal or sensitive information.')}</p></section>`;
}
function home(){crumb();return `${homeHero()}${homeContextStrip()}${comparisonPanel()}${domainNote()}<div class="section-head atlas-heading"><div><div class="eyebrow">01 / ${t('交互全景图','INTERACTIVE ATLAS')}</div><h2>${t('具身闭环','The embodied loop')}</h2></div><a class="text-link" href="#references">${t('浏览全部文献','Browse all sources')} ↗</a></div>${researchLoop()}${tree()}${overviewPanels()}${directoryCards()}${repositoryCommunity()}`;}
function mediaCatalog(){return [...D.localMedia||[],...(D.media||[]).map(m=>({...m,id:'legacy-'+m.categoryId,kind:'image',title:t('RoboCasa 仿真场景','RoboCasa simulated scenes'),categoryIds:[m.categoryId],domains:['robotics']}))];}
function mediaFor(type,id) {
 const active=mediaCatalog().filter(item=>item.approved&&!item.original&&!item.homeOnly);
 if(type==='stage')return active.filter(item=>visible(item)&&(item.stageIds||[]).includes(id));
 if(type==='category')return [];
 const candidates=active.filter(item=>(item.methodIds||[]).includes(id));
 const local=candidates.filter(visible), entity=nodes.get(id);
 if(domain==='all'||!entity?.domains.includes('common'))return local;
 // A shared mechanism can retain its separately labeled source-domain example.
 return [...local,...candidates.filter(item=>!visible(item)&&!local.some(own=>own.kind===item.kind))];
}
function sourceMediaPanel(type,entity) {
 if(type!=='method')return '';
 const linked=(D.sourceOnlyMedia||[]).filter(item=>visible(item)&&(item.methodIds||[]).includes(entity.id));
 if(!linked.length)return '';
 const figures=linked.filter(item=>item.authorFigureUrl), other=linked.filter(item=>!item.authorFigureUrl);
 const gallery=figures.length?`<section class="author-figure-list"><h3>${t('作者项目原图','Figures from the authors')}</h3>${figures.map(item=>`<button type="button" data-author-figure="${esc(item.id)}"><strong>${esc(item.title)}</strong><span>${t('查看并放大','Open & zoom')} ⤢</span></button>`).join('')}</section>`:'';
 const links=other.length?`<details class="source-only-links"><summary>${t('作者网站上的图与演示','Figures and demos on author sites')} (${other.length})</summary><ul>${other.map(item=>`<li><a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a></li>`).join('')}</ul></details>`:'';
 return gallery+links;
}

const mediaLicense=m=>m.rightsStatus==='rightsholder_redistribution_grant_not_verified'?t('来源未标明复用许可','Reuse license not stated by source'):m.license;
function localMediaCard(m,context){
 const title=esc(m.title||m.caption||''),key=context+'-'+m.id,duration=m.duration??m.durationSeconds;
 const credit=m.original?'':`<span class="media-credit">${esc(m.attribution||'')}</span>`;
 const details=[m.caption?`<p>${esc(m.caption)}</p>`:'',credit,m.sourceUrl?`<a href="${esc(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('来源','Source')} ↗</a>`:'',m.license?`<p>${m.licenseUrl?`<a href="${esc(m.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(mediaLicense(m))}</a>`:esc(mediaLicense(m))}</p>`:'',m.modified?`<p>${esc(m.modified)}</p>`:'',m.replayBundle?`<a href="${esc(m.replayBundle)}" download="evaluation-replays.zip">${t('下载复算示例','Download worked examples')}</a>`:''].join('');
 const dimensions=Number.isFinite(m.width)&&m.width>0&&Number.isFinite(m.height)&&m.height>0?{width:Math.round(m.width),height:Math.round(m.height)}:null;
 const size=dimensions?` style="--media-ratio:${dimensions.width}/${dimensions.height};--media-native-width:${Math.max(dimensions.width,320)}px" data-media-ratio="${dimensions.width}/${dimensions.height}"`:'';
 const view=m.kind==='video'?`<div class="demo-masthead"><span class="demo-indicator" aria-hidden="true"></span><span>${m.mediaType==='atlas-evaluation'?t('可复算教学演示','WORKED EXAMPLE'):m.mediaType==='stage-worked-example'?t('教学实验','WORKED EXAMPLE'):t('项目演示','PROJECT DEMO')}</span><span class="demo-duration">${Number.isFinite(duration)?esc(Number(duration.toFixed(2))+' s'):''}</span><button class="local-play" data-play-local="${esc(m.id)}">${t('播放动态','Play motion')}</button></div><div class="local-video-frame"${size}><video data-media-id="${esc(m.id)}" preload="none" muted loop playsinline ${m.poster?`poster="${esc(m.poster)}"`:''} aria-label="${esc(m.alt||m.title)}" aria-describedby="${esc(key)}" controls></video></div>`:`<button class="open-media" data-enlarge-media="${esc(m.id)}" aria-label="${esc(t('放大图片：','Enlarge image: ')+(m.title||''))}"><img src="${esc(m.src)}" alt="${esc(m.alt||m.title)}" loading="lazy" decoding="async"><span>${t('放大','Enlarge')} ⤢</span></button>`;
 return `<figure class="local-media-card ${m.kind==='video'?'demo-card':'figure-card'}" data-local-media-card="${esc(m.id)}">${view}<figcaption id="${esc(key)}"><strong>${title}</strong>${(domain!=='all'&&!visible(m))?`<p class="case-domain">${esc(m.domains.map(d=>labels()[d]).join(' / '))} · ${t('同机制案例','Case of the same mechanism')}</p>`:''}${m.displayScope?`<p class="media-scope">${esc(m.displayScope)}</p>`:''}${details?informationNote(t('来源','Source'),details,'media-information'):''}</figcaption>${m.kind==='video'?`<span class="local-video-status sr-only" role="status" aria-live="polite"></span>`:''}</figure>`;
}
function simpleFlow(type,entity){
 const f=(D.flows||[]).find(f=>f.type===type&&f.id===entity.id);if(!f)return '';
 const row=steps=>'<ol class="flow-steps">'+steps.map((step,i)=>'<li class="flow-step flow-tone-'+(i===0?'input':i===steps.length-1?'output':'process')+'"><span class="flow-index">'+String(i+1).padStart(2,'0')+'</span><span class="flow-step-text">'+esc(step)+'</span>'+(i<steps.length-1?'<b aria-hidden="true">→</b>':'')+'</li>').join('')+'</ol>';
 const body=f.branches?.length?'<div class="flow-alternatives">'+f.branches.map((b,i)=>'<div class="flow-branch" data-flow-lane="'+i+'"><h3><span aria-hidden="true">'+String.fromCharCode(65+i)+'</span>'+esc(b.label)+'</h3>'+row(b.steps)+'</div>').join('')+'</div>':row(f.steps);
 const feedback=f.feedback?'<div class="flow-feedback"><span aria-hidden="true">↶</span><span>'+esc(f.feedback)+'</span></div>':'';
 return '<section class="simple-flow" data-flow-entity="'+esc(type+'-'+entity.id)+'" aria-label="'+esc(entity.title+' · '+t('机制流程','Mechanism flow'))+'"><div class="visual-label"><span class="panel-letter">A</span>'+t('机制流程','MECHANISM')+'</div>'+body+feedback+'</section>';
}
function visualTriplet(type,entity,context){
 const authorPanel=sourceMediaPanel(type,entity);
 const eligible=mediaFor(type,entity.id),preferred=(D.mediaPresentations||[]).find(p=>p.type===type&&p.id===entity.id)?.mediaOrder||[];
 const rank=m=>{const i=preferred.indexOf(m.id);return i<0?preferred.length: i;};
 const all=[...eligible].sort((a,b)=>rank(a)-rank(b)),key=context+'-'+entity.id;
 const video=all.find(m=>m.kind==='video'),figure=all.find(m=>m.kind==='image'),primary=[video,figure].filter(Boolean),remaining=all.filter(m=>!primary.includes(m));
 const lead=video?'<div class="study-demo" data-panel="demo">'+localMediaCard(video,key+'-primary')+'</div>':'';
 const evidence=figure?'<div class="study-evidence" data-panel="figure"><div class="visual-label"><span class="panel-letter">'+(video?'C':'B')+'</span>'+t('论文与项目图','RESEARCH FIGURE')+'</div>'+localMediaCard(figure,key+'-primary')+'</div>':'';
 const media=all.length?'<div class="study-media">'+(video?'<div class="visual-label"><span class="panel-letter">B</span>'+t('研究实例','RESEARCH EXAMPLE')+'</div>':'')+lead+evidence+(remaining.length?'<details class="more-media"><summary>'+t('更多相关素材','More research media')+' <span>('+remaining.length+')</span></summary><div class="local-media-gallery">'+remaining.map(m=>localMediaCard(m,key+'-more')).join('')+'</div></details>':'')+'</div>':'<p class="media-gap">'+t('相关实拍 / 项目演示待补充','Research imagery and project demos to be added')+'</p>';
 return '<section class="research-visuals research-board" data-visual-entity="'+esc(type+'-'+entity.id)+'" data-presentation="'+(video?'demo-led':'figure-led')+'">'+simpleFlow(type,entity)+(all.length||!authorPanel?media:'')+authorPanel+'</section>';
}

function methodVisual(n,context='method'){return visualTriplet('method',n,context);}
function updateLocalButton(video,playing){const button=video.closest('.local-media-card')?.querySelector('[data-play-local]');if(button){button.textContent=playing?t('暂停动态','Pause motion'):t('播放动态','Play motion');button.setAttribute('aria-pressed',String(playing));}}
function pauseLocalMedia(video,userInitiated=false){if(userInitiated){video.dataset.userPaused='true';rememberMediaPause(video.dataset.mediaId,true);}if(!video.paused){video.dataset.pauseReason=userInitiated?'user':'program';video.pause?.();}updateLocalButton(video,false);}
function playLocalMedia(video,manual=false){if((motionPaused()||video.dataset.userPaused==='true')&&!manual)return;const m=(D.localMedia||[]).find(x=>x.id===video.dataset.mediaId&&x.approved&&x.kind==='video');if(!m)return;if(manual){video.dataset.userPaused='false';rememberMediaPause(video.dataset.mediaId,false);}if(!video.getAttribute('src'))video.setAttribute('src',m.src);video.muted=true;video.loop=true;video.playsInline=true;const status=video.closest('.local-media-card')?.querySelector('.local-video-status');const result=video.play?.();updateLocalButton(video,true);if(result?.catch)result.catch(()=>{pauseLocalMedia(video);if(status)status.textContent=t('未能自动播放，请点击播放或使用播放器控件。','Playback did not start. Use Play or the native video controls.');});}

function teardownLocalMedia(){mediaObserver?.disconnect();mediaObserver=null;$$('video[data-media-id]').forEach(v=>pauseLocalMedia(v));}
function mediaIsShown(video){for(let p=video;p;p=p.parentNode){if(p.hidden||p.tagName==='DETAILS'&&!p.open&&p.getAttribute('open')===null)return false;}return true;}
function setupLocalMedia(){mediaObserver?.disconnect();const videos=$$('video[data-media-id]');if(!videos.length)return;for(const v of videos){if(v.dataset.mediaBound==='true')continue;v.dataset.mediaBound='true';v.dataset.userPaused=String(userPausedMedia.has(v.dataset.mediaId));v.addEventListener('play',()=>{v.dataset.userPaused='false';rememberMediaPause(v.dataset.mediaId,false);updateLocalButton(v,true);});v.addEventListener('pause',()=>{if(v.dataset.pauseReason!=='program'){v.dataset.userPaused='true';rememberMediaPause(v.dataset.mediaId,true);}v.dataset.pauseReason='';updateLocalButton(v,false);});v.addEventListener('error',()=>{const status=v.closest('.local-media-card')?.querySelector('.local-video-status');if(status){status.classList.remove('sr-only');status.textContent=t('视频暂不可用；可查看来源说明。','Video unavailable. Source notes remain available.');}});}if(typeof window.IntersectionObserver==='function'){mediaObserver=new window.IntersectionObserver(entries=>{for(const entry of entries)entry.isIntersecting&&mediaIsShown(entry.target)?playLocalMedia(entry.target):pauseLocalMedia(entry.target);},{rootMargin:'0px',threshold:.2});videos.forEach(v=>mediaObserver.observe(v));}}
function applyMotion(){document.documentElement.dataset.motion=motionPaused()?'paused':'active';const button=$('#motionToggle');button.textContent=motionPaused()?t('动态已暂停','Motion paused'):t('减少动态','Reduce motion');button.setAttribute('aria-pressed',String(motionPaused()));$$('[data-action="toggle-motion"]').forEach(b=>{b.textContent=motionPaused()?t('播放动态','Play motion'):t('暂停动态','Pause motion');b.dataset.paused=String(motionPaused());});if(motionPaused()){$$('video[data-media-id]').forEach(v=>pauseLocalMedia(v));}setupLocalMedia();}
function categoryVisual(c,compact=false){return simpleFlow('category',c);}
function categoryCard(c){const leaves=c.leaves.filter(visible);if(!leaves.length)return '';return `<article class="category-card"><span class="category-id">${c.id.toUpperCase()} / ${countText(leaves.length,'个子模块','methods')}</span><h2><a href="#category/${c.id}">${esc(c.title)} ↗</a></h2><p>${esc(c.description)}</p><div class="leaf-links">${leaves.map(n=>`<a href="#node/${n.id}"><span>${esc(n.title)}</span><small>${countText(referenceList([...n.references,...n.latest]).length,'来源','sources')}</small><span aria-hidden="true">↗</span></a>`).join('')}</div></article>`;}
function stagePage(id){const s=D.stages.find(x=>x.id===id);if(!s)return notFound();crumb([[s.title,`stage/${id}`]]);const i=D.stages.indexOf(s);return header(`${s.number} / ${t('研发环节','RESEARCH STAGE')}`,s.title+' · '+s.subtitle,s.description+' '+s.topics)+domainNote()+visualTriplet('stage',s,'page-stage')+refSection(s.references)+refSection(s.latest,true,s.references)+`<section class="category-grid">${s.categories.map(categoryCard).join('')}</section><div class="next-prev"><a href="#home"><small>← ${t('返回全景','Back to the atlas')}</small>${t('交互全景树','Interactive tree')}</a><a href="#stage/${D.stages[(i+1)%4].id}"><small>${i===3?t('反馈回流','Close the loop'):t('下一环节','Next stage')} →</small>${esc(D.stages[(i+1)%4].title)}</a></div>`;}
function paperCard(r,withNodes=false){if(!r)return '';let host;try{host=new URL(r.url).hostname.replace('www.','');}catch{host=t('原始来源','Original source');}return `<article class="reference-card" data-reference-id="${esc(r.id)}"><div class="ref-meta"><time>${esc(r.dateDisplay||r.date||r.year||r.dateLabel||t('日期未标注','Date not recorded'))}</time></div><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><h3>${esc(r.name)} <span aria-hidden="true">↗</span></h3></a>${r.summary?`<p class="ref-desc key-idea">${esc(short(r.summary,lang==='zh'?110:240))}</p>`:''}${r.repoUrl?`<a class="repository-link" href="${esc(r.repoUrl)}" target="_blank" rel="noopener noreferrer">GitHub${r.repoLabel?` · ${esc(r.repoLabel)}`:''} ↗</a>`:''}<details class="source-metadata"><summary>${t('详情','Details')}</summary>${r.kind?`<p class="ref-desc ref-kind">${esc(r.kind)}</p>`:''}${r.dateLabel?`<p class="ref-desc">${esc(r.dateLabel)}</p>`:''}${r.revision?`<p class="ref-desc">${t('最近修订','Revised')} ${esc(r.revision)}</p>`:''}${r.summary?`<p class="ref-desc">${esc(r.summary)}</p>`:''}${r.boundary?`<p class="ref-desc">${t('适用边界','Scope and limitations')}: ${esc(r.boundary)}</p>`:''}${r.repoNote?`<p class="ref-desc">${t('代码范围','Repository scope')}: ${esc(r.repoNote)}</p>`:''}${r.projectUrl&&r.projectUrl!==r.url?`<a class="repository-link" href="${esc(r.projectUrl)}" target="_blank" rel="noopener noreferrer">${t('项目页面','Project page')} ↗</a>`:''}<div class="ref-origin">${esc(host)} · ${t('核查','Checked')} ${esc(r.verified||D.updated)}</div>${r.evidence?`<p class="ref-desc">${esc(r.evidence)}</p>`:''}${sourceVersions(r)}${withNodes?`<div class="ref-links">${r.nodes.filter(id=>nodes.has(id)).map(id=>`<a href="#node/${id}">${esc(nodes.get(id).title)} ↗</a>`).join('')}</div>`:''}</details></article>`;}
function refSection(ids,recent=false,excluded=[],relatedIds=ids){
 const direct=referenceList(ids,excluded),seen=new Set([...direct.map(r=>r.id),...excluded.map(id=>refs.get(id)?.id)]);
 const related=[];
 if(domain!=='all'&&direct.length<5)for(const id of relatedIds){
  const r=refs.get(id);
  if(!r||visible(r)||seen.has(r.id))continue;
  seen.add(r.id);related.push(r);
  if(direct.length+related.length>=5)break;
 }
 const comparisons=related.length?`<div class="related-reading"><h3>${t('跨领域延伸阅读','Cross-field reading')}</h3><p>${t('这些论文从其他领域讨论同一机制，实际验证范围以所标领域为准。','These works illustrate the same mechanism in other fields. Each entry identifies its evaluation domain.')}</p><ul>${related.map(r=>`<li data-related-id="${esc(r.id)}"><small>${esc(r.domains.map(d=>labels()[d]||d).join(' / '))} · ${esc(r.date||r.year||'')}</small><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.name)} ↗</a><p>${esc(short(r.summary,lang==='zh'?140:245))}</p></li>`).join('')}</ul></div>`:'';
 const title=recent?t('近期论文与资源','Recent papers & resources'):t('代表作与基础资料','Foundational works & resources');
 const intro=recent?`<p class="reading-window">${t('本栏选读 2024–2026 年发布的论文与资源。','Selected papers and resources released in 2024–2026.')}</p>`:'';
 const grid=direct.length?`<div class="reference-grid">${direct.map(r=>paperCard(r)).join('')}</div>`:'';
 const empty=!direct.length&&!related.length?`<div class="empty-state">${t('暂无匹配来源','No matching sources')}</div>`:'';
 return `<section class="ref-section" data-direct-count="${direct.length}" data-related-count="${related.length}"><div class="ref-head"><h2>${title}</h2><span class="count">${direct.length+related.length}</span></div>${intro}${grid}${comparisons}${empty}</section>`;
}
function familyReadings(c,leaves){
 const allChildren=c.leaves;
 const found=[...(c.references||[]),...allChildren.flatMap(n=>n.references)],latest=[...(c.latest||[]),...allChildren.flatMap(n=>n.latest)];
 const visibleFound=[...(c.references||[]),...leaves.flatMap(n=>n.references)],visibleLatest=[...(c.latest||[]),...leaves.flatMap(n=>n.latest)];
 const recentIds=new Set(latest.map(id=>refs.get(id)?.id));
 const keepFound=id=>!recentIds.has(refs.get(id)?.id);
 return refSection(visibleFound.filter(keepFound),false,[],found.filter(keepFound))+refSection(visibleLatest,true,found.filter(keepFound),latest);
}
function categoryPage(id){const c=cats.get(id);if(!c)return notFound();const s=c.stage,leaves=c.leaves.filter(visible);crumb([[s.title,`stage/${s.id}`],[c.title,`category/${id}`]]);return header(`${id.toUpperCase()} / ${t('方法族','METHOD FAMILY')}`,c.title,c.description)+categoryVisual(c)+domainNote()+(id==='2c'?`<div class="domain-note">${t('直接回归、自回归、扩散与流匹配描述输出建模；动作分块描述时间组织。它们可与模仿学习、强化学习及 VLA 架构组合，不是互斥的学习信号。','Direct regression, autoregression, diffusion and flow matching describe output modeling; action chunking describes temporal organization. They can be combined with imitation learning, reinforcement learning and VLA architectures rather than treated as mutually exclusive learning signals.')}</div>`:'')+`<div class="section-head"><div><h2>${t('打开子模块','Explore individual methods')}</h2><p>${t('展开阅读摘要，或进入完整详情。','Expand a summary or open the complete details.')}</p></div></div>${leaves.map(n=>`<details class="leaf-detail"><summary>${esc(n.title)} <span class="count">${countText(referenceList([...n.references,...n.latest]).length,'来源','sources')}</span></summary><div class="detail-inner"><p>${esc(short(n.body.join('\n'),lang==='zh'?240:550))}</p><div class="chips">${n.domains.map(tag).join('')}</div><a class="detail-link" href="#node/${n.id}">${t('阅读完整方法与参考资料','Read the complete method & references')} ↗</a></div></details>`).join('')}${familyReadings(c,leaves)}<div class="next-prev"><a href="#stage/${s.id}"><small>← ${t('上一级','Parent stage')}</small>${esc(s.title)}</a><a href="#home"><small>${t('重新定位','Reorient')} →</small>${t('返回全景树','Back to the atlas tree')}</a></div>`;}
function nodePage(id){const n=nodes.get(id);if(!n)return notFound();const s=n.stage,c=n.category;crumb([[s.title,`stage/${s.id}`],[c.title,`category/${c.id}`],[n.title,`node/${id}`]]);return header(`${id.toUpperCase()} / ${t('细分方法','INDIVIDUAL METHOD')}`,n.title,'')+`<div class="node-layout"><div><div class="chips">${n.domains.map(tag).join('')}<span class="chip">${esc(c.title)}</span></div>${n.notes?.length?informationNote(t('阅读边界','Reading boundaries'),n.notes.map(esc).join('<br>')):''}${D.methodClarifications?.[n.id]?`<p class="method-clarification">${esc(D.methodClarifications[n.id].description)}</p>`:''}${methodVisual(n,'page')}<article class="node-article">${n.body.map(md).join('')}</article>${n.branches?.length&&branchList(n).length?`<section class="node-subtree"><h2>${t('沿技术分支深入','Explore technical branches')}</h2>${branchList(n).map(b=>subBranch(b)).join('')}</section>`:''}${refSection(n.references)}${refSection(n.latest,true,n.references)}</div><aside class="node-aside"><div class="panel"><div class="panel-kicker">${t('同一方法族','IN THE SAME FAMILY')}</div>${c.leaves.filter(x=>x.id!==id&&visible(x)).map(x=>`<a class="small-link" href="#node/${x.id}">${esc(x.title)} ↗</a>`).join('')}<p style="margin-top:1rem">${t('内容快照','Content snapshot')}: ${D.updated}</p></div></aside></div><div class="next-prev"><a href="#category/${c.id}"><small>← ${t('返回方法族','Back to the family')}</small>${esc(c.title)}</a><a href="#home"><small>${t('重新定位','Reorient')} →</small>${t('返回全景树','Back to the atlas tree')}</a></div>`;}
function referencesPage(kind="all"){crumb([[t('参考文献库','Reference library'),'references']],'root');return header(t('追溯原始证据','TRACE THE EVIDENCE'),t('参考文献库','Reference library'),t('论文、作者项目、代码与官方文档各有证据范围。日期按已确认的首次发表或发布记录，保留原有精度；核查日期另列。动态资源不伪造首发日期，也不声称穷尽最新研究。','Papers, author projects, code and official documentation each have their own evidence scope. Dates use established first publications or releases at the recorded precision; checking dates are separate. Living resources are not assigned invented release dates, and coverage is not exhaustive.'))+domainNote()+`<div class="filter-row"><input class="inline-search" id="refSearch" type="search" placeholder="${t('按名称、年份、关键词筛选…','Filter by title, year or keyword…')}" aria-label="${t('筛选参考文献','Filter references')}"><select id="refType" aria-label="${t('参考文献类别','Reference category')}"><option value="all"${kind!=='recent'?' selected':''}>${t('全部来源','All sources')}</option><option value="recent"${kind==='recent'?' selected':''}>${t('近期收录','Recent additions')}</option><option value="foundational">${t('代表作与基础','Foundational')}</option></select><span class="mini" id="refCount" role="status" aria-live="polite"></span></div><div class="reference-grid" id="allReferences"></div>`;}
function renderRefs(){const target=$('#allReferences');if(!target)return;const q=($('#refSearch')?.value||'').trim().toLowerCase(),kind=$('#refType')?.value||'all';const list=canonicalRefs.filter(r=>visible(r)&&(kind==='all'||(kind==='recent'?r.section==='latest':r.section!=='latest'))&&r.searchText.includes(q));list.sort((a,b)=>(b.section==='latest')-(a.section==='latest')||(b.date||String(b.year||0)).localeCompare(a.date||String(a.year||0)));$('#refCount').textContent=countText(list.length,'条来源','sources');target.innerHTML=list.length?list.map(r=>paperCard(r,true)).join(''):`<div class="empty-state">${t('没有找到匹配来源。试试更短的关键词。','No matching sources. Try a shorter keyword.')}</div>`;}
function mediaCredits(){const all=[...(D.media||[]),...(D.localMedia||[])];return informationNote(t('素材与许可清单','Media credits & licenses'),`<p>${t('总览横幅为原创概念插画，不计入研究素材覆盖；驾驶与机器人领域首页使用相应项目来源画面。流程图用于概括机制；方法页收录作者论文图和项目演示。原始来源、修改与许可记录如下，单项许可不扩展到全站。','The overview banner is original conceptual artwork and does not count toward research-media coverage; the driving and robotics homepages use their corresponding project-source imagery. Flowcharts summarize mechanisms; method pages display author figures and project demonstrations. Sources, modifications and licenses follow; asset-specific licenses do not apply to the entire site.')}</p><ul class="media-credit-list">${all.map(m=>`<li><strong>${esc(m.title||m.caption)}</strong><p>${esc(m.attribution)}</p>${m.sourceUrl?`<a href="${esc(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('原始来源','Original source')} ↗</a> · `:''}${m.licenseUrl?`<a href="${esc(m.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(mediaLicense(m))}</a>`:esc(mediaLicense(m))}${m.original?`<p>${esc(m.caption)}</p>`:''}${m.modified?`<p>${esc(m.modified)}</p>`:''}</li>`).join('')}</ul>`,'credits-directory');}
function guide(){crumb([[t('阅读与更新','Reading & updates'),'guide']],'root');const panels=[
['01',t('研发闭环与运行闭环','Research and runtime loops'),t('<strong>研发：</strong>任务与约束 → 数据与环境 → 建模学习 → 集成运行 → 评测诊断 → 下一版本。反馈可以回到任何有问题的环节，经典规划与控制可绕过学习。','<strong>Research:</strong> tasks and constraints → data and environments → modeling and learning → integration and operation → evaluation and diagnosis → the next version. Feedback can return to any problematic stage; classical planning and control can bypass learning.'),t('<strong>运行：</strong>观测 → 状态估计或内部表示 → 决策与动作 → 环境 → 新观测。冻结参数的系统同样存在运行闭环。','<strong>Runtime:</strong> observation → state estimation or internal representation → decisions and actions → environment → new observations. Systems with frozen parameters still have runtime feedback loops.')],
['02',t('同一棵树，不是两个孤岛','One tree, connected fields'),t('自动驾驶和机器人共享表征、学习、规划、控制、安全与验证工具。通过领域视图突出差异，而不是重复维护两套方法定义。','Autonomous driving and robotics share tools for representation, learning, planning, control, safety and verification. Field views highlight differences without maintaining duplicate method definitions.'),t('驾驶重点是交通交互、道路规则与车辆约束；机器人还需细分导航、操作、足式与移动操作的机体和任务条件。','Driving emphasizes traffic interaction, road rules and vehicle constraints. Robotics additionally requires attention to embodiment and task conditions in navigation, manipulation, legged locomotion and mobile manipulation.')],
['04',t('代表作与近期收录各司其职','Foundational and recent works serve different roles'),t('<strong>代表作：</strong>建立机制坐标，包括原始方法、可靠基线、公开数据集和必要的官方工具资料。','<strong>Foundational works:</strong> establish the mechanisms through original methods, reliable baselines, public datasets and essential official tool documentation.'),t('<strong>近期收录：</strong>显示已核验日期与证据范围。预印本不等于经同行评审的定论；缺少条目时明确留空。所有近期标签都受核查日期和检索范围限制，不承诺绝对最新或穷尽覆盖。','<strong>Recent additions:</strong> show verified dates and evidence scope. Preprints are not peer-reviewed conclusions; missing entries stay explicitly empty. All recent labels are limited by verification dates and search scope, without claiming absolute recency or exhaustive coverage.')],
['05',t('可更新快照，不是实时订阅','An updateable snapshot, not a live subscription'),t(`本版内容快照：<strong>${D.updated}</strong>。中英文共享节点 ID、引用关系和知识结构；语言切换不会改变论文原始链接。`,`Content snapshot: <strong>${D.updated}</strong>. Chinese and English share node IDs, citation relationships and structure. Switching languages preserves original paper URLs.`),t('更新流程：核对原始来源 → 更新两种语言的节点和参考资料 → 校验结构与链接 → 发布新版本。此版本没有实时论文源、后台自动更新或定时任务。','Update process: check original sources → update nodes and references in both languages → validate structure and links → publish a new version. This version has no live paper feed, automatic background updates or scheduled jobs.')],
['06',t('离线阅读与本地偏好','Offline reading and local preferences'),t('所有界面、方法说明和文献资料均随页面保存，离线可浏览与搜索。访问原始论文和外部网站仍需联网；本地短视频随离线文件保存，默认静音循环并按需加载；减少动态可暂停。此版不使用第三方视频播放器。手机聊天应用内的文件预览器可能不执行脚本或支持播放器，请用浏览器打开。','The interface, method descriptions and reference records are stored with the page for offline browsing and search. Original papers and external sites still require a connection. Local clips are included offline and load on demand, with muted looping playback and a reduced-motion control. This edition does not use third-party video players. In-app previews may not support scripts or players; open the file in a browser.'),t('语言、字号、领域与树的展开状态只保存在当前浏览器中。图谱本身没有账号系统、遥测或访问分析；图像与视频均从本地文件加载。此技术与文献版本不包含个人研究分析，也不链接私有项目。','Language, text size, field and expanded branches are stored only in the current browser. The atlas itself has no account system, telemetry or analytics; images and videos load from local files. This technical and reference edition excludes personal research analysis and private project links.')]
];return header(t('如何阅读这张图','HOW TO READ THE ATLAS'),t('保持结构清楚，让判断可以更新。','Keep the structure clear. Keep conclusions open.'),t('阅读、素材许可与证据边界。GitHub Issues 为公开反馈渠道，请勿提交个人或敏感信息。','Reading, media licenses and evidence boundaries. GitHub Issues is a public feedback channel; do not include personal or sensitive information.'))+`<section class="guide-grid">${panels.slice(0,2).map(p=>`<div class="panel"><div class="panel-kicker">${p[0]}</div><h2>${p[1]}</h2><p>${p[2]}</p><p>${p[3]}</p></div>`).join('')}<div class="panel wide"><div class="panel-kicker">03 / ${t('正交坐标','ORTHOGONAL AXES')}</div><h2>${t('六个独立坐标，不放在同一互斥列表里','Six independent axes, not one mutually exclusive list')}</h2>${[
[t('学习信号','Learning signal'),t('示教与监督、自监督预测、对比匹配、奖励与偏好','Demonstrations and supervision, self-supervised prediction, contrastive matching, rewards and preferences')],
[t('输出与表示','Outputs & representations'),t('像素、对象、BEV、占据、潜变量；回归、AR、扩散与流匹配','Pixels, objects, BEV, occupancy and latent variables; regression, autoregression, diffusion and flow matching')],
[t('优化算法','Optimization'),t('梯度优化、PPO、SAC、价值学习与模型学习','Gradient optimization, PPO, SAC, value learning and model learning')],
[t('训练耦合范围','Training coupling'),t('局部模块、联合优化、端到端；是否保留中间监督','Local modules, joint optimization and end-to-end training; whether intermediate supervision is retained')],
[t('运行时组织','Runtime organization'),t('直接策略、世界模型规划、技能编排；快慢层、动作块与异步队列','Direct policies, world-model planning and skill orchestration; fast/slow layers, action chunks and asynchronous queues')],
[t('输入与任务接口','Inputs & task interface'),t('视觉、语言、状态与动作；任务条件、机体和控制频率','Vision, language, states and actions; task conditioning, embodiment and control frequency')]
].map(([a,b])=>`<div class="axis-row"><strong>${a}</strong><span>${b}</span></div>`).join('')}<p>${t('例如 π0 可同时具有 VLA 接口、流匹配动作生成、模仿学习与动作分块。3DGS 是场景表示与渲染方法，JEPA 是表征学习路线，CBF 是显式约束工具，它们可以出现在同一系统中。','For example, π0 can combine a VLA interface, flow-matching action generation, imitation learning and action chunking. 3DGS is a scene representation and rendering method, JEPA is a representation-learning approach, and CBF is an explicit constraint tool. These can coexist in one system.')}</p></div>${panels.slice(2).map(p=>`<div class="panel ${p[0]==='06'?'wide':''}"><div class="panel-kicker">${p[0]}</div><h2>${p[1]}</h2><p>${p[2]}</p><p>${p[3]}</p></div>`).join('')}</section>${mediaCredits()}`;}
function notFound(){crumb([[t('未找到节点','Node not found'),'home']]);return header('404',t('这个节点暂不存在','This node does not exist'),t('返回全景树重新选择。','Return to the atlas tree to choose another node.'))+`<a class="primary-link" href="#home">${t('返回全景树','Back to the atlas tree')} ↗</a>`;}
function render(){if($('#mediaDialog').open)$('#mediaDialog').close();teardownLocalMedia();prepare();shell();nav();const [type,id]=activeHash().split('/');$('#main').innerHTML=['home','atlas'].includes(type)?home():type==='news'?fieldNotes(id):['topics','arxiv','principles','reproductions'].includes(type)?reservedPage(type):type==='stage'?stagePage(id):type==='category'?categoryPage(id):type==='node'?nodePage(id):type==='references'?referencesPage(id):type==='guide'?guide():notFound();if(type==='references')renderRefs();const title=type==='node'?nodes.get(id)?.title:type==='category'?cats.get(id)?.title:type==='stage'?D.stages.find(s=>s.id===id)?.title:['news','topics','arxiv','principles','reproductions'].includes(type)?primaryEntries().find(x=>x[1]===type)[2]:type==='references'?t('参考文献库','Reference library'):type==='guide'?t('阅读与更新','Reading & updates'):t('交互全景树','Interactive tree');document.title=(['home','atlas'].includes(type)?t('自动驾驶与机器人技术图谱','Autonomous Driving & Robotics Roadmap'):(title||t('未找到节点','Node not found')))+' · Embodied Atlas';$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');setupLocalMedia();}
function renderTree(focusId){const old=$('#panorama');if(!old){render();save('branches',JSON.stringify([...open]));if(focusId)$(`[data-expand="${focusId}"]`)?.focus({preventScroll:true});return;}teardownLocalMedia();const y=window.scrollY;if(document.fullscreenElement===old){const holder=document.createElement('div');holder.innerHTML=tree();old.innerHTML=holder.firstElementChild.innerHTML;}else{old.outerHTML=tree();}if(focusId)$(`[data-expand="${focusId}"]`)?.focus({preventScroll:true});window.scrollTo({top:y,behavior:'instant'});save('branches',JSON.stringify([...open]));setupLocalMedia();}
const searchIndex=new Map();
const mediaNameIndex=new Map();
for(const locale of ['zh','en']){
 const data=window.ATLAS_I18N[locale];
 const references=new Map(data.references.map(r=>[r.id,r.name]));
 for(const media of data.localMedia||[])for(const id of media.methodIds||[]){
  const fields=media.domains.includes('common')?['all','driving','robotics']:['all',...media.domains];
  for(const field of fields){
   const key=field+'/'+id;
   mediaNameIndex.set(key,(mediaNameIndex.get(key)||'')+' '+media.title.toLowerCase());
  }
 }
 for(const stage of data.stages)for(const category of stage.categories)for(const node of category.leaves){
  const terms=[node.id,node.title,category.title,stage.title,...node.body,...[...node.references,...node.latest].map(id=>references.get(id)||''),JSON.stringify(node.branches||[])];
  searchIndex.set(node.id,(searchIndex.get(node.id)||'')+' '+terms.join(' ').toLowerCase());
 }
}
function search(q){const query=q.trim().toLowerCase(),list=[...nodes.values()].filter(n=>visible(n)&&(!query||searchIndex.get(n.id).includes(query)||mediaNameIndex.get(domain+'/'+n.id)?.includes(query)));$('#searchMeta').textContent=query?`${countText(list.length,'个匹配节点','matching nodes')} · ${labels()[domain]}`:t('输入关键词搜索全部节点，也可从以下方法开始。','Search all nodes, or start with one of these methods.');$('#searchResults').innerHTML=list.length?list.map(n=>`<a class="search-result" href="#node/${n.id}"><small>${esc(n.stage.title)} / ${esc(n.category.title)}</small><h3>${esc(n.title)}</h3><p>${esc(short(n.body.join(' '),lang==='zh'?100:200))}</p></a>`).join(''):`<div class="empty-state">${t('没有匹配结果。试试中文方法名、英文模型名或更短的关键词。','No matches. Try a Chinese method name, an English model name or a shorter keyword.')}</div>`;}
function changeLanguage(value){lang=value;save('language',lang);const q=$('#searchInput').value,searchOpen=$('#searchDialog').open;render();if(searchOpen){$('#searchInput').value=q;search(q);}$('#announcer').textContent=t('已切换为中文','Switched to English');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');
if(b?.dataset.compare){
 const entry=comparisonTopics().find(item=>item.id===b.dataset.compare);
 if(entry){
  comparison=entry.id;
  $('#comparisonBody').innerHTML=comparisonBody(entry);
  $$('[data-compare]').forEach(choice=>choice.setAttribute('aria-pressed',String(choice.dataset.compare===entry.id)));
 }
 return;
}
if(b?.dataset.lang){changeLanguage(b.dataset.lang);return;}if(b?.dataset.domain){domain=b.dataset.domain;save('domain',domain);render();return;}if(b?.dataset.authorFigure){
 const item=(D.sourceOnlyMedia||[]).find(m=>m.id===b.dataset.authorFigure&&m.authorFigureUrl);
 if(item)openFigure({...item,src:item.authorFigureUrl});
 return;
}
if(b?.dataset.enlargeMedia){const m=mediaCatalog().find(m=>m.id===b.dataset.enlargeMedia&&m.approved&&m.kind==='image');if(m)openFigure(m);return;}if(b?.dataset.playLocal){const v=b.closest('.local-media-card')?.querySelector('video');if(v)b.getAttribute('aria-pressed')==='true'?pauseLocalMedia(v,true):playLocalMedia(v,true);return;}if(b?.dataset.view){treeView=b.dataset.view;save('tree-view',treeView);renderTree();return;}if(b?.dataset.expand){const id=b.dataset.expand;open.has(id)?open.delete(id):open.add(id);renderTree(id);return;}if(b?.dataset.action){switch(b.dataset.action){case'toggle-motion':motion=motionPaused()?'active':'paused';save('motion',motion);applyMotion();b.focus();break;case'explore':$('#panorama').scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});break;case'expand-level':{const bs=allBranches();const level=bs.find(b=>!open.has(b.id)&&(!b.parent||open.has(b.parent)))?.depth;if(level!==undefined)bs.filter(b=>b.depth===level).forEach(b=>open.add(b.id));renderTree();break;}case'expand-all':allBranches().forEach(b=>open.add(b.id));renderTree();break;case'collapse-all':open.clear();renderTree();break;case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#panorama').requestFullscreen();}catch{$('#announcer').textContent=t('当前浏览器无法全屏，可继续在页面内阅读。','Full screen is unavailable in this browser. You can continue reading on the page.');}break;}return;}if(e.target.closest('#searchResults a'))$('#searchDialog').close();if(e.target.closest('.workspace')&&!e.target.closest('#menuToggle')){$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');}});
document.addEventListener('input',e=>{if(e.target.id==='refSearch')renderRefs();});
document.addEventListener('change',e=>{if(e.target.id==='refType')renderRefs();});
$('#motionToggle').addEventListener('click',()=>{motion=motionPaused()?'active':'paused';save('motion',motion);applyMotion();$('#motionToggle').focus();});
reducedMotion?.addEventListener?.('change',()=>{if(motion==='system')applyMotion();});
function setFigureZoom(detail) {
 const viewport=$('#figureViewport');
 viewport.dataset.zoom=detail?'detail':'fit';
 viewport.setAttribute('tabindex',detail?'0':'-1');
 viewport.scrollLeft=0;
 viewport.scrollTop=0;
 $('#figureZoom').textContent=detail?t('适应窗口','Fit to window'):t('放大细节','Zoom in');
}
function openFigure(media) {
 const image=$('#mediaImage'), source=$('#figureOriginal'),status=$('#figureStatus');
 source.hidden=!media.authorFigureUrl;
 if(media.authorFigureUrl){
  source.setAttribute('href',media.authorFigureUrl);
  source.textContent=t('在作者网站查看原图','Open original on author site')+' ↗';
 }
 status.textContent=media.authorFigureUrl?t('正在载入作者原图…','Loading the author’s figure…'):'';
 image.onload=()=>{status.textContent='';};
 image.onerror=()=>{status.textContent=t('图片暂时无法显示。','The figure is temporarily unavailable.');};
 image.setAttribute('src',media.src);
 image.setAttribute('alt',media.alt||media.title);
 $('#mediaImageCaption').textContent=media.title||media.caption;
 $('#closeMedia').setAttribute('aria-label',t('关闭图片','Close image'));
 setFigureZoom(false);
 $('#mediaDialog').showModal();
 $('#closeMedia').focus();
}
$('#figureZoom').addEventListener('click',()=>setFigureZoom($('#figureViewport').dataset.zoom!=='detail'));
$('#closeMedia').addEventListener('click',()=>$('#mediaDialog').close());
$('#mediaDialog').addEventListener('click',e=>{if(e.target===$('#mediaDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});});
$('#sidebar').addEventListener('click',e=>{if(e.target.closest('a')){$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');}});
$('#fontSize').addEventListener('change',e=>{font=e.target.value;document.documentElement.dataset.font=font;save('font',font);});
$('#menuToggle').addEventListener('click',()=>{const state=$('#sidebar').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',String(state));});
$('#openSearch').addEventListener('click',()=>{$('#searchDialog').showModal();$('#searchInput').value='';search('');$('#searchInput').focus();});
$('#closeSearch').addEventListener('click',()=>$('#searchDialog').close());
$('#searchInput').addEventListener('input',e=>search(e.target.value));
$('#searchInput').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing)return;e.preventDefault();const a=$('#searchResults a');if(a){$('#searchDialog').close();location.hash=a.hash;}});
$('#searchDialog').addEventListener('click',e=>{if(e.target===$('#searchDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#openSearch').click();}if(e.key==='Escape'){if($('#searchDialog').open){e.preventDefault();$('#searchDialog').close();$('#openSearch').focus();return;}if($('#sidebar').classList.contains('open'))$('#menuToggle').focus();$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');}});
document.addEventListener('fullscreenchange',()=>{const b=$('[data-action="fullscreen"]');if(b)b.textContent=document.fullscreenElement?t('退出全屏','Exit full screen'):t('全屏查看','Full screen');});
window.addEventListener('hashchange',()=>{if($('#searchDialog').open)$('#searchDialog').close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
})();
